<script lang="ts">
import {onMount} from 'svelte';import {locations} from '../fixtures/locations';import type {Location} from '../domain/location';import type {Profile} from '../domain/publication';import {parseRoute} from './routeState';import {filterLocations,initialFilters,type FilterState} from '../features/locations/filterState';import MapView from '../map/MapView.svelte';import {makeExportModel} from '../export/exportModel';import {previewExport} from '../export/previewExport';import {LocalLocationRepository} from '../api/LocalLocationRepository';
let profile:Profile='curated';let scenario='ready';let selected:Location|undefined=locations[0];let search='';let region='all';let filters:FilterState=initialFilters;let showMap=false;let showExport=false;let localMode=false;let localStatus:'idle'|'loading'|'ready'|'error'|'no-release'='idle';let localError='';let loaded:readonly Location[]=[];let release='synthetic-2026.09';let localProfile:'official'|'secondary'|'community'='official';$:filters={search,region,category:'all'};$:source=localMode?loaded:(profile==='community'?locations.slice(0,1):locations);$:visibleLocations=filterLocations(source,filters);$:exportPreview=previewExport(makeExportModel(visibleLocations,profile,release));
const syncRoute=()=>{const r=parseRoute(window.location.hash);if(r.kind==='location')selected=(localMode?loaded:locations).find(x=>x.id===r.facilityId)??selected;else if(r.kind==='home')selected=(localMode?loaded:locations)[0];};const select=(id:string)=>{selected=source.find(x=>x.id===id)??selected;window.location.hash=`/locations/${id}?profile=${profile}`};
async function loadLocal(){localStatus='loading';localError='';try{const result=await new LocalLocationRepository().list(localProfile);loaded=result.locations;release=result.releaseId;localStatus='ready';syncRoute();}catch(error){const kind=error&&typeof error==='object'&&'kind'in error?(error as {kind:string}).kind:'error';localStatus=kind==='no-release'?'no-release':'error';localError=error instanceof Error?error.message:'Local V2 response was rejected safely.';loaded=[];selected=undefined;}}
onMount(()=>{localMode=new URLSearchParams(window.location.search).get('mode')==='local-v2';syncRoute();if(localMode)void loadLocal();window.addEventListener('hashchange',syncRoute);return()=>window.removeEventListener('hashchange',syncRoute)});
</script>
<svelte:head><title>Until Every Cage · evidence desk</title></svelte:head><main><header class="top"><a class="wordmark" href="/v2-preview/#/">UNTIL EVERY CAGE <span>V2 / FIELD NOTE</span></a><a href="/ethics.html">Ethics &amp; safeguards ↗</a></header><section class="intro"><p class="eyebrow">EVIDENCE DESK · {localMode?'LOCAL V2 API':'SYNTHETIC PREVIEW'}</p><h1>See what a record can—and cannot—tell us.</h1><p class="lede">{localMode?'Explicit local integration mode. No fixture or V1 fallback is used.':'A quiet, inspectable view of fictional locations.'}</p></section><section class="toolbar" aria-label="Preview controls"><label>Profile<select bind:value={profile} onchange={()=>{if(localMode){localProfile=profile==='community'?'community':'official';void loadLocal();}}}><option value="curated">Curated release</option><option value="community">Community claims</option></select></label><label>Search locations<input aria-label="Search locations" bind:value={search} placeholder="Name, region, category" /></label><label>Region<select aria-label="Filter by region" bind:value={region}><option value="all">All regions</option>{#each [...new Set(source.map(x=>x.region))] as option}<option value={option}>{option}</option>{/each}</select></label>{#if !localMode}<label>State<select bind:value={scenario}><option value="ready">Ready</option><option value="loading">Loading</option><option value="empty">Empty</option><option value="error">Error</option><option value="restricted">Restricted</option></select></label>{/if}</section>{#if profile==='community'}<div class="warning" role="note"><strong>Unreviewed community claim</strong><span>Not verified by Until Every Cage.</span></div>{/if}{#if localMode&&localStatus==='loading'}<div class="state">Loading the local V2 release…</div>{:else if localMode&&(localStatus==='error'||localStatus==='no-release')}<div class="state error" role="alert"><h2>{localStatus==='no-release'?'No promoted release':'Could not load local V2 data'}</h2><p>{localError}</p></div>{:else if scenario==='loading'}<div class="state">Loading the fixture…</div>{:else if scenario==='empty'}<div class="state"><h2>No eligible records</h2></div>{:else if scenario==='error'}<div class="state error" role="alert"><h2>Could not load preview</h2></div>{:else if scenario==='restricted'}<div class="state"><h2>Preview withheld</h2></div>{:else}<div class="content"><aside><div class="list-head"><span>VISIBLE RECORDS</span><strong>{visibleLocations.length}</strong></div>{#each visibleLocations as location}<button class:active={selected?.id===location.id} onclick={()=>select(location.id)}><span class="dot"></span><span><strong>{location.name}</strong><small>{location.region} · {location.category}</small></span></button>{:else}<p>No records match these filters.</p>{/each}</aside><article>{#if selected}<p class="eyebrow">RECORD / {selected.id}</p><h2>{selected.name}</h2><p class="region">{selected.region} · {selected.category}</p><div class="facts"><div><span>OBSERVED</span><strong>{selected.observed}</strong></div><div><span>MAP STATUS</span><strong>{selected.lat===null?'Not available':'Approximate display point'}</strong></div></div>{/if}</article></div>{/if}<div class="phase-controls"><button onclick={()=>showMap=!showMap}>{showMap?'Hide map':'Show map'}</button><button onclick={()=>showExport=!showExport}>Preview export</button></div>{#if showMap}<MapView items={visibleLocations} selectedId={selected?.id??null}/>{/if}{#if showExport}<section class="export-preview"><p class="eyebrow">IN-MEMORY EXPORT PREVIEW</p><strong>{profile} · {release}</strong><p>Loaded results only. This preview is not a live or complete export.</p><pre>{exportPreview}</pre></section>{/if}<footer><span>{localMode?'Local V2 mode · no fixture fallback':'Method preview · no live requests'}</span></footer></main>
